//
// Terminator translations:
//   fallthrough(n) → __state = n; continue;
//   goto(n)        → __state = n; continue;
//   branch(c,t,e)  → __state = (c) ? t : e; continue;
//   switch(...)    → switch(scrut) { case v: __state=t; ...; default: __state=d; }
