        // path, which types the call from its default-promoted arguments.
        // The linker resolves the address through the existing frame ABI.
        const unresolvedUnprototyped = this.relocatable && funcDecl &&
          !(funcDecl.definition || funcDecl).body &&
          (funcDecl.definition || funcDecl).type.hasUnspecifiedParams &&
          expr.arguments.length !== (funcDecl.definition || funcDecl).type.getParamTypes().length;
